-- Linuxコマンド道場 データベース（データベース設計書に対応）
-- Supabase の SQL Editor に貼り付けて実行する。何度実行しても壊れないように書いてある。
--
-- 設計書との違い（Supabase / PostgreSQL に合わせたもの）
--  * INT Auto Increment → INT GENERATED BY DEFAULT AS IDENTITY
--  * DATETIME → TIMESTAMPTZ、JSON → JSONB
--  * users に auth_user_id（Supabase認証のユーザーID）を追加：
--    ログイン中のユーザーと users の行を結びつけ、行単位のアクセス制限（RLS）に使う。
--    既存の認証コールバック（app/auth/callback/route.ts）が、この列で upsert している。

/* ========== テーブル ========== */

create table if not exists users (
  id            int generated by default as identity primary key,
  auth_user_id  uuid not null unique references auth.users(id) on delete cascade,
  google_id     varchar(255) not null unique,
  email         varchar(255) not null unique,
  name          varchar(100) not null,
  xp            int not null default 0,                 -- 【Want】累計XP
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table if not exists lessons (
  id          int generated by default as identity primary key,
  code        varchar(50)  not null unique,             -- URLに使う（ls, cd, mkdir）
  title       varchar(100) not null,
  sort_order  int not null,
  category    varchar(30)  not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists lesson_steps (
  id               int generated by default as identity primary key,
  lesson_id        int not null references lessons(id) on delete cascade,
  step_number      int not null,
  body             text not null,                       -- 課題文
  hint             text not null,
  clear_condition  jsonb not null,                      -- 形式は supabase/README.md を参照
  setup_data       jsonb,                               -- 1ステップ目だけ。2以降は NULL（前の状態を引き継ぐ）
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (lesson_id, step_number)
);

create table if not exists lesson_progress (
  id            int generated by default as identity primary key,
  user_id       int not null references users(id) on delete cascade,
  lesson_id     int not null references lessons(id) on delete cascade,
  completed_at  timestamptz not null default now(),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (user_id, lesson_id)
);

create table if not exists questions (
  id             int generated by default as identity primary key,
  lesson_id      int references lessons(id) on delete set null,
  question_type  varchar(20) not null check (question_type in ('quiz','practical','repair','scenario')),
  command_tag    varchar(30) not null,
  title          varchar(100),
  body           text not null,
  choices        jsonb,                                 -- 確認テストのみ
  correct_index  int check (correct_index between 0 and 3),
  explanation    text,
  setup_data     jsonb,                                 -- 実技・修復・シナリオ
  source         varchar(10) not null default 'manual' check (source in ('manual','ai')),
  created_by     int references users(id) on delete cascade,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create table if not exists test_results (
  id         int generated by default as identity primary key,
  user_id    int not null references users(id) on delete cascade,
  lesson_id  int references lessons(id) on delete set null,
  test_type  varchar(20) not null check (test_type in ('quiz','practical','repair','review','weakness','scenario')),
  score      int not null,
  total      int not null,
  taken_at   timestamptz not null default now()
);

create table if not exists answer_logs (
  id              int generated by default as identity primary key,
  user_id         int not null references users(id) on delete cascade,
  question_id     int not null references questions(id) on delete cascade,
  test_result_id  int references test_results(id) on delete set null,
  selected_index  int check (selected_index between 0 and 3),
  is_correct      boolean not null,
  is_review       boolean not null default false,
  answered_at     timestamptz not null default now()
);

create table if not exists badges (                     -- 【Want】
  id          int generated by default as identity primary key,
  code        varchar(50)  not null unique,
  name        varchar(100) not null,
  description varchar(255) not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists user_badges (                -- 【Want】
  id         int generated by default as identity primary key,
  user_id    int not null references users(id) on delete cascade,
  badge_id   int not null references badges(id) on delete cascade,
  earned_at  timestamptz not null default now(),
  unique (user_id, badge_id)
);

-- 弱点分析（ユーザー×コマンドの直近5回）と復習（問題ごとの最新回答）を速くするための索引
create index if not exists answer_logs_user_time on answer_logs (user_id, answered_at desc);
create index if not exists answer_logs_user_question on answer_logs (user_id, question_id, answered_at desc);
create index if not exists questions_lesson_type on questions (lesson_id, question_type);
create index if not exists test_results_user_lesson on test_results (user_id, lesson_id, test_type);

/* ========== 更新日時を自動で更新 ========== */

create or replace function set_updated_at() returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['users','lessons','lesson_steps','lesson_progress','questions','badges'] loop
    execute format('drop trigger if exists trg_%1$s_updated on %1$s', t);
    execute format('create trigger trg_%1$s_updated before update on %1$s for each row execute function set_updated_at()', t);
  end loop;
end $$;

/* ========== 行単位のアクセス制限（RLS） ==========
   ・レッスン／ステップ／問題／バッジの「中身」は、ログイン済みなら誰でも読める（書き込みは不可。管理は Supabase 側で行う）
   ・ユーザー個別のデータ（進捗・結果・回答）は、本人の行だけ読み書きできる
   ・弱点対策でAIが作った「そのユーザー専用の問題」(created_by) は、本人だけが読める */

-- ログイン中の users.id を返す（RLSの条件から使う）
create or replace function current_user_id() returns int
language sql stable security definer set search_path = public as $$
  select id from users where auth_user_id = auth.uid()
$$;

alter table users           enable row level security;
alter table lessons         enable row level security;
alter table lesson_steps    enable row level security;
alter table lesson_progress enable row level security;
alter table questions       enable row level security;
alter table test_results    enable row level security;
alter table answer_logs     enable row level security;
alter table badges          enable row level security;
alter table user_badges     enable row level security;

do $$
declare p record;
begin  -- 再実行できるよう、このファイルで作るポリシーを一旦消す
  for p in select policyname, tablename from pg_policies where schemaname = 'public' and policyname like 'dojo\_%' loop
    execute format('drop policy %I on %I', p.policyname, p.tablename);
  end loop;
end $$;

create policy dojo_users_select on users for select to authenticated using (auth_user_id = auth.uid());
create policy dojo_users_insert on users for insert to authenticated with check (auth_user_id = auth.uid());
create policy dojo_users_update on users for update to authenticated using (auth_user_id = auth.uid()) with check (auth_user_id = auth.uid());

create policy dojo_lessons_read on lessons      for select to authenticated using (true);
create policy dojo_steps_read   on lesson_steps for select to authenticated using (true);
create policy dojo_badges_read  on badges       for select to authenticated using (true);
create policy dojo_questions_read on questions  for select to authenticated using (created_by is null or created_by = current_user_id());

create policy dojo_progress_select on lesson_progress for select to authenticated using (user_id = current_user_id());
create policy dojo_progress_insert on lesson_progress for insert to authenticated with check (user_id = current_user_id());
create policy dojo_progress_update on lesson_progress for update to authenticated using (user_id = current_user_id()) with check (user_id = current_user_id());

create policy dojo_results_select on test_results for select to authenticated using (user_id = current_user_id());
create policy dojo_results_insert on test_results for insert to authenticated with check (user_id = current_user_id());

create policy dojo_answers_select on answer_logs for select to authenticated using (user_id = current_user_id());
create policy dojo_answers_insert on answer_logs for insert to authenticated with check (user_id = current_user_id());

create policy dojo_ubadges_select on user_badges for select to authenticated using (user_id = current_user_id());
create policy dojo_ubadges_insert on user_badges for insert to authenticated with check (user_id = current_user_id());

grant usage on schema public to authenticated;
grant select on lessons, lesson_steps, questions, badges to authenticated;
grant select, insert, update on users, lesson_progress to authenticated;
grant select, insert on test_results, answer_logs, user_badges to authenticated;
grant usage, select on all sequences in schema public to authenticated;
